def mailchimp_create_campaign(title, audience_id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0461000" if __import__("os").path.isdir("./environment_mix/0461000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()

    # Load world (single-row document; datastore may be empty)
    world_rows = _load("world.json")
    if isinstance(world_rows, dict):
        world = world_rows
        world_rows = [world]
    elif isinstance(world_rows, list) and len(world_rows) > 0 and isinstance(world_rows[0], dict):
        world = world_rows[0]
    else:
        world = None

    # Ensure observable service dynamics: record every call in a request log persisted in world.json.
    # Since schema doesn't declare an audit collection, we attach a vendor-like request log under
    # a top-level key without changing existing arrays' shapes.
    def _record(status, error_code=None):
        nonlocal world, world_rows
        latency_ms = int(round((time.time() - t0) * 1000))
        ts = _now_iso()
        if world is None:
            world = {
                "bot_user_id": "U_BOT",
                "channels": [],
                "messages": [],
                "audiences": [],
                "campaigns": [],
                "spreadsheets": [],
            }
            world_rows = [world]
        reqlog = world.get("_request_log")
        if not isinstance(reqlog, list):
            reqlog = []
            world["_request_log"] = reqlog
        reqlog.append(
            {
                "id": "req_" + uuid.uuid4().hex[:18],
                "tool": "mailchimp_create_campaign",
                "timestamp": ts,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
            }
        )
        ctr = world.get("_counters")
        if not isinstance(ctr, dict):
            ctr = {}
            world["_counters"] = ctr
        ctr["requests_total"] = int(ctr.get("requests_total", 0) or 0) + 1
        ctr["mailchimp_create_campaign_total"] = int(ctr.get("mailchimp_create_campaign_total", 0) or 0) + 1
        _save("world.json", world_rows)

    # Validate inputs
    if not isinstance(title, str) or not title.strip():
        _record("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    if not isinstance(audience_id, str) or not audience_id.strip():
        _record("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "audience_id is required and must be a non-empty string")

    # If world is missing, no audiences exist / no connection context exists; treat as unauthorized per tool contract
    if world is None:
        _record("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Mailchimp is not connected or account is not accessible in this environment")

    audiences = world.get("audiences", [])
    if not isinstance(audiences, list):
        audiences = []

    # Audience must exist
    aud = next((a for a in audiences if isinstance(a, dict) and a.get("id") == audience_id), None)
    if aud is None:
        _record("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Referenced audience_id was not found or is not accessible", audience_id=audience_id)

    campaigns = world.get("campaigns", [])
    if not isinstance(campaigns, list):
        campaigns = []
        world["campaigns"] = campaigns

    # Generate a unique campaign id
    existing_ids = {c.get("id") for c in campaigns if isinstance(c, dict)}
    # Prefer a monotonic cmp-N format when possible
    n = 1
    while True:
        cid = f"cmp-{n}"
        if cid not in existing_ids:
            break
        n += 1

    rec = {
        "id": cid,
        "title": title.strip(),
        "audience_id": audience_id,
        "status": "draft",
        "emails_sent": 0,
        "opens": 0,
        "clicks": 0,
        "send_time": None,
    }
    campaigns.append(rec)

    # Persist mutation + request log
    _record("success", None)
    return {"campaign": rec}

