    if not isinstance(row, list) or any(not isinstance(v, str) for v in row):
        return _err("VALIDATION_ERROR", "row must be an array of strings", row=row)

    world = _load("world.json")
    if not isinstance(world, dict):
        world = {}

    # Ensure base shape
    if "spreadsheets" not in world or not isinstance(world.get("spreadsheets"), list):
        world["spreadsheets"] = [
            {"id": "sheet-1", "name": "Audience_Roster", "worksheets": [{"title": "Roster", "values": []}]},
            {"id": "sheet-2", "name": "Q1_Content_Budget", "worksheets": [{"title": "Sheet1", "values": []}]},
        ]

    key = spreadsheet.strip()
    target = None
    for s in world.get("spreadsheets", []):
        if not isinstance(s, dict):
            continue
        if s.get("id") == key or s.get("name") == key:
            target = s
            break
    if target is None:
        return _err("NOT_FOUND", "No spreadsheet matching the provided name or id", spreadsheet=spreadsheet)

    worksheets = target.get("worksheets")
    if not isinstance(worksheets, list) or not worksheets:
        return _err("CONFLICT", "Spreadsheet has no worksheets", spreadsheet_id=target.get("id"))

    ws0 = worksheets[0]
    if not isinstance(ws0, dict):
        return _err("CONFLICT", "First worksheet is invalid", spreadsheet_id=target.get("id"))

    values = ws0.get("values")
    if not isinstance(values, list):
        ws0["values"] = []
        values = ws0["values"]

    before = len(values)
    values.append(list(row))
    after = len(values)

    if after != before + 1:
        return _err("CONFLICT", "Append did not apply")

    try:
        _save("world.json", world)
    except Exception:
        return _err("CONFLICT", "Failed to persist appended row")

    return {
        "spreadsheet": {"id": target.get("id"), "name": target.get("name")},
        "worksheet_title": ws0.get("title"),
        "updated_range": f"{ws0.get('title') or 'Sheet1'}!A{after}",
