def slack_get_channel_messages(channel_id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0461000" if __import__("os").path.isdir("./environment_mix/0461000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(channel_id, str) or not channel_id.strip():
        return _err("VALIDATION_ERROR", "channel_id must be a non-empty string", channel_id=channel_id)
    channel_id = channel_id.strip()

    world = _load("world.json")
    if not isinstance(world, dict):
        world = {}

    # Ensure base channels/messages exist
    changed = False
    if "channels" not in world or not isinstance(world.get("channels"), list):
        world["channels"] = [
            {"id": "C_ANALYTICS", "name": "analytics", "is_private": False},
            {"id": "C_CONTENT", "name": "content", "is_private": False},
            {"id": "C_MKT", "name": "marketing", "is_private": False},
        ]
        changed = True
    if "messages" not in world or not isinstance(world.get("messages"), list):
        world["messages"] = []
        changed = True

    # Validate channel exists
    ch = None
    for c in world.get("channels", []):
        if isinstance(c, dict) and c.get("id") == channel_id:
            ch = c
            break
    if ch is None:
        if changed:
            try:
                _save("world.json", world)
            except Exception:
                return _err("CONFLICT", "Failed to persist datastore changes")
        return _err("NOT_FOUND", "channel_id was not found or is not accessible", channel_id=channel_id)

    # Filter messages for channel
    msgs = []
    for m in world.get("messages", []):
        if not isinstance(m, dict):
            continue
        if m.get("channel_id") == channel_id:
            msgs.append(m)

    # Persist any base-shape initialization
    if changed:
        try:
            _save("world.json", world)
        except Exception:
            return _err("CONFLICT", "Failed to persist datastore changes")

    # Sort by ts ascending (Slack commonly returns newest-first, but datastore ts may be arbitrary; keep stable)
    def _ts_key(x):
        v = x.get("ts")
        return v if isinstance(v, str) else ""
    msgs_sorted = sorted(msgs, key=_ts_key)

    return {
        "channel": {"id": ch.get("id"), "name": ch.get("name"), "is_private": bool(ch.get("is_private"))},
        "messages": msgs_sorted,
        "total": len(msgs_sorted),
    }

