    t0 = time.time()

    world_rows = _load("world.json")
    if isinstance(world_rows, dict):
        world = world_rows
        world_rows = [world]
    elif isinstance(world_rows, list) and len(world_rows) > 0 and isinstance(world_rows[0], dict):
        world = world_rows[0]
    else:
        world = None

    def _record(status, error_code=None):
        nonlocal world, world_rows
        latency_ms = int(round((time.time() - t0) * 1000))
        ts = _now_iso()
        if world is None:
            world = {
                "bot_user_id": "U_BOT",
                "channels": [],
                "messages": [],
                "audiences": [],
                "campaigns": [],
                "spreadsheets": [],
            }
            world_rows = [world]
        reqlog = world.get("_request_log")
        if not isinstance(reqlog, list):
            reqlog = []
            world["_request_log"] = reqlog
        reqlog.append(
            {
                "id": "req_" + uuid.uuid4().hex[:18],
                "tool": "slack_send_channel_message",
                "timestamp": ts,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
            }
        )
        ctr = world.get("_counters")
        if not isinstance(ctr, dict):
            ctr = {}
            world["_counters"] = ctr
        ctr["requests_total"] = int(ctr.get("requests_total", 0) or 0) + 1
        ctr["slack_send_channel_message_total"] = int(ctr.get("slack_send_channel_message_total", 0) or 0) + 1
        _save("world.json", world_rows)

    # Validate inputs
    if not isinstance(channel_id, str) or not channel_id.strip():
        _record("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "channel_id is required and must be a non-empty string")
    if not isinstance(text, str) or not text.strip():
