    if not isinstance(channels, list):
        channels = []

    ch = next((c for c in channels if isinstance(c, dict) and c.get("id") == channel_id), None)
    if ch is None:
        _record("error", "NOT_FOUND")
        return _err("NOT_FOUND", "channel_id was not found or is not accessible", channel_id=channel_id)

